    pub gitignore: bool,
    pub parser: String,
    pub parser_config: Option<serde_json::Value>,
    pub run_in_band: bool,
    pub silent: bool,
    pub stdin: bool,
    pub custom_options: HashMap<String, serde_json::Value>,
}

impl Default for Options {
    fn default() -> Self {
        Self {
            transform: "./transform.js".to_string(),
            cpus: None,
            verbose: 0,
            dry: false,
            print: false,
            babel: true,
            extensions: "cjs,es,es6,js,jsx,mjs,ts,tsx".to_string(),
            fail_on_error: false,
            ignore_config: Vec::new(),
            ignore_pattern: Vec::new(),
            gitignore: false,
            parser: "babel".to_string(),
            parser_config: None,
            run_in_band: false,
            silent: false,
            stdin: false,
            custom_options: HashMap::new(),
        }
    }
}

pub enum ParseOutcome {
    Run {
        options: Options,
        positional_arguments: Vec<String>,
    },
    Exit {
        exit_code: i32,
        message: String,
    },
}

