pub fn parse(args: &[String]) -> ParseOutcome {
    let mut options = Options::default();
    let mut positional_arguments = Vec::new();
    let mut raw_custom: HashMap<String, serde_json::Value> = HashMap::new();

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && arg != "-" {
            // It is an option
            let mut opt_name = arg.clone();
            let mut explicit_value: Option<String> = None;

            if let Some(eq_pos) = arg.find('=') {
                opt_name = arg[..eq_pos].to_string();
                explicit_value = Some(arg[eq_pos + 1..].to_string());
            }

            match opt_name.as_str() {
                "-h" | "--help" => {
                    return ParseOutcome::Exit {
                        exit_code: 0,
                        message: get_help_text(),
                    };
                }
                "--version" => {
                    return ParseOutcome::Exit {
                        exit_code: 0,
                        message: get_version_text(),
                    };
                }
                "-t" | "--transform" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --transform requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    options.transform = val;
                }
                "-c" | "--cpus" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --cpus requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    if let Ok(n) = val.parse::<usize>() {
                        options.cpus = Some(n);
                    }
                }
                "-v" | "--verbose" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --verbose requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    if val != "0" && val != "1" && val != "2" {
                        return ParseOutcome::Exit {
                            exit_code: 1,
                            message: format!(
                                "Error: --verbose must be one of the values 0,1,2\n\n---\n\n{}",
                                get_help_text()
                            ),
                        };
                    }
                    options.verbose = val.parse::<u8>().unwrap_or(0);
                }
                "-d" | "--dry" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.dry = val;
                }
                "--no-dry" => {
                    options.dry = false;
                }
                "-p" | "--print" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.print = val;
                }
                "--no-print" => {
                    options.print = false;
                }
                "--babel" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.babel = val;
                }
                "--no-babel" => {
                    options.babel = false;
                }
                "--extensions" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --extensions requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    options.extensions = val;
                }
                "--fail-on-error" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.fail_on_error = val;
                }
                "--no-fail-on-error" => {
                    options.fail_on_error = false;
                }
                "--ignore-config" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --ignore-config requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    options.ignore_config.push(val);
                }
                "--ignore-pattern" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --ignore-pattern requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    options.ignore_pattern.push(val);
                }
                "--gitignore" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.gitignore = val;
                }
                "--no-gitignore" => {
                    options.gitignore = false;
                }
                "--parser" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --parser requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    if !["babel", "babylon", "flow", "ts", "tsx"].contains(&val.as_str()) {
                        return ParseOutcome::Exit {
                            exit_code: 1,
                            message: format!(
                                "Error: --parser must be one of the values babel,babylon,flow,ts,tsx\n\n---\n\n{}",
                                get_help_text()
                            ),
                        };
                    }
                    options.parser = val;
                }
                "--parser-config" => {
                    let val = match explicit_value {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                                i += 1;
                                args[i].clone()
                            } else {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!(
                                        "Missing value: --parser-config requires a value\n\n---\n\n{}",
                                        get_help_text()
                                    ),
                                };
                            }
                        }
                    };
                    let path = Path::new(&val);
                    match fs::read_to_string(path) {
                        Ok(content) => match serde_json::from_str(&content) {
                            Ok(json) => options.parser_config = Some(json),
                            Err(e) => {
                                return ParseOutcome::Exit {
                                    exit_code: 1,
                                    message: format!("Error parsing parser-config: {}\n", e),
                                };
                            }
                        },
                        Err(e) => {
                            return ParseOutcome::Exit {
                                exit_code: 1,
                                message: format!("Error reading parser-config file {}: {}\n", val, e),
                            };
                        }
                    }
                }
                "--run-in-band" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.run_in_band = val;
                }
                "--no-run-in-band" => {
                    options.run_in_band = false;
                }
                "-s" | "--silent" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.silent = val;
                }
                "--no-silent" => {
                    options.silent = false;
                }
                "--stdin" => {
                    let val = match explicit_value {
                        Some(ref v) => v == "1",
                        None => true,
                    };
                    options.stdin = val;
                }
                "--no-stdin" => {
                    options.stdin = false;
                }
                _ => {
                    // Unknown / custom option
                    let real_name = opt_name
                        .trim_start_matches('-')
                        .strip_prefix("no-")
                        .unwrap_or_else(|| opt_name.trim_start_matches('-'))
                        .to_string();

                    let val: serde_json::Value = if opt_name.starts_with("--no-") {
                        serde_json::Value::Bool(false)
                    } else if let Some(v) = explicit_value {
                        serde_json::from_str(&v).unwrap_or(serde_json::Value::String(v))
                    } else if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                        i += 1;
                        let next_val = &args[i];
                        serde_json::from_str(next_val)
                            .unwrap_or_else(|_| serde_json::Value::String(next_val.clone()))
                    } else {
                        serde_json::Value::Bool(true)
                    };

                    if let Some(existing) = raw_custom.get_mut(&real_name) {
                        if let serde_json::Value::Array(ref mut arr) = existing {
                            arr.push(val);
                        } else {
                            let old = existing.clone();
                            if old == serde_json::Value::Bool(true) {
                                *existing = serde_json::Value::Array(vec![val]);
                            } else {
                                *existing = serde_json::Value::Array(vec![old, val]);
                            }
                        }
                    } else {
                        raw_custom.insert(real_name, val);
                    }
                }
            }
        } else {
            // Positional argument
            positional_arguments.push(arg.clone());
        }

        i += 1;
    }

    if positional_arguments.is_empty() && !options.stdin {
        return ParseOutcome::Exit {
            exit_code: 1,
            message: format!(
                "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
                get_help_text()
            ),
        };
    }

    options.custom_options = raw_custom;

    ParseOutcome::Run {
        options,
        positional_arguments,
    }
}
