{"file_text":"use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
use regex::Regex;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone)]
pub struct IgnoreEngine {
    raw_patterns: Vec<String>,
    glob_set: Option<GlobSet>,
}

impl Default for IgnoreEngine {
    fn default() -> Self {
        Self::new()
    }
}

impl IgnoreEngine {
    pub fn new() -> Self {
        Self {
            raw_patterns: Vec::new(),
            glob_set: None,
        }
    }

    pub fn add_pattern(&mut self, val: &str) {
        let val = val.trim();
        if val.is_empty() || val.starts_with('#') {
            return;
        }

        let pattern = val.to_string();
        if !pattern.contains('/') && !pattern.contains('\\') {
            self.raw_patterns.push(format!("**/{}", pattern));
            self.raw_patterns.push(format!("**/{}/", pattern));
            self.raw_patterns.push(format!("**/{}/<star><star>", pattern).replace("<star>", "*"));
        } else if pattern.ends_with('/') || pattern.ends_with('\\') {
            let clean = pattern.trim_end_matches(['/', '\\']);
            self.raw_patterns.push(format!("**/{}/**", clean));
            self.raw_patterns.push(format!("{}/**", clean));
            self.raw_patterns.push(format!("**/{}", clean));
            self.raw_patterns.push(clean.to_string());
        }
        self.raw_patterns.push(pattern);
        self.glob_set = None;
    }

    pub fn add_patterns(&mut self, patterns: &[String]) {
        for p in patterns {
            self.add_pattern(p);
        }
    }

    pub fn add_from_file<P: AsRef<Path>>(&mut self, path: P) {
        if let Ok(content) = fs::read_to_string(path) {
            for line in content.lines() {
                self.add_pattern(line);
            }
        }
    }

    fn build_glob_set(&mut self) {
        if self.glob_set.is_some() {
            return;
        }
        let mut builder = GlobSetBuilder::new();
        for pat in &self.raw_patterns {
            let normalized = pat.replace('\\', "/");
            if let Ok(glob) = GlobBuilder::new(&normalized)
                .literal_separator(false)
                .backslash_escape(false)
                .build()
            {
                builder.add(glob);
            }
        }
        self.glob_set = builder.build().ok();
    }

    pub fn should_ignore(&mut self, path: &str) -> bool {
        if self.raw_patterns.is_empty() {
            return false;
        }
        self.build_glob_set();

        let normalized = path.replace('\\', "/");
        let re = Regex::new(r"^(?:\.\.?[/\\])+").unwrap();
        let stripped = re.replace_all(&normalized, "").to_string();

        if let Some(ref set) = self.glob_set {
            if set.is_match(&normalized) {
                return true;
            }
            if stripped != normalized && set.is_match(&stripped) {
                return true;
            }
            // Also test basename match if pattern matches basename
            if let Some(filename) = Path::new(&normalized).file_name().and_then(|n| n.to_str()) {
                if set.is_match(filename) {
                    return true;
                }
            }
        }

        false
    }
}
