{"path":"/workspace/codebase/src/discovery.rs","command":"create","summary":"Create src/discovery.rs","security_risk":"LOW","file_text":"use crate::ignore::IgnoreEngine;
use std::fs;
use std::path::Path;

pub fn parse_extensions(ext_str: &str) -> Vec<String> {
    if ext_str.is_empty() {
        return Vec::new();
    }
    ext_str
        .split(',')
        .map(|s| {
            let s = s.trim();
            if s.starts_with('.') {
                s.to_string()
            } else {
                format!(".{}", s)
            }
        })
        .collect()
}

fn has_valid_extension(file_path: &str, extensions: &[String]) -> bool {
    if extensions.is_empty() {
        return true;
    }
    let p = Path::new(file_path);
    if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
        let dotted = format!(".{}", ext);
        extensions.iter().any(|e| e == &dotted)
    } else {
        false
    }
}

fn dir_files(
    dir_path: &str,
    extensions: &[String],
    ignore_engine: &mut IgnoreEngine,
    result: &mut Vec<String>,
) {
    let entries = match fs::read_dir(dir_path) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut entry_paths: Vec<_> = entries
        .filter_map(|res| res.ok().map(|e| e.path()))
        .collect();
    entry_paths.sort();

    for path_buf in entry_paths {
        let path_str = path_buf.to_string_lossy().to_string();
        match fs::metadata(&path_buf) {
            Err(_) => {
                print!("Skipping path \"{}\" which does not exist.\n", path_str);
            }
            Ok(meta) => {
                if ignore_engine.should_ignore(&path_str) {
                    continue;
                }
                if meta.is_dir() {
                    let mut dir_with_slash = path_str.clone();
                    if !dir_with_slash.ends_with('/') && !dir_with_slash.ends_with('\\') {
                        dir_with_slash.push('/');
                    }
                    dir_files(&dir_with_slash, extensions, ignore_engine, result);
                } else if meta.is_file() {
                    if has_valid_extension(&path_str, extensions) {
                        result.push(path_str);
                    }
                }
            }
        }
    }
}

pub fn get_all_files(
    paths: &[String],
    extensions: &[String],
    ignore_engine: &mut IgnoreEngine,
) -> Vec<String> {
    let mut files = Vec::new();

    for p in paths {
        let path_buf = Path::new(p);
        match fs::symlink_metadata(path_buf) {
            Err(_) => {
                eprint!("Skipping path {} which does not exist. \n", p);
            }
            Ok(meta) => {
                if meta.is_dir() {
                    dir_files(p, extensions, ignore_engine, &mut files);
                } else {
                    if has_valid_extension(p, extensions) && !ignore_engine.should_ignore(p) {
                        files.push(p.clone());
                    }
                }
            }
        }
    }

    files
}
