{"path":"/workspace/codebase/bridge/transform-host.js","command":"create","summary":"Create bridge/transform-host.js","file_text":"'use strict';

const fs = require('fs');
const path = require('path');
const readline = require('readline');
const writeFileAtomic = require('write-file-atomic');
const core = require('../src/core.js');
const getParser = require('../src/getParser.js');

const transformFile = process.argv[2];
const babelOpt = process.argv[3];

if (babelOpt === 'babel') {
  try {
    const defaultPlugins = [
      require('@babel/plugin-transform-class-properties').default,
      require('@babel/plugin-transform-nullish-coalescing-operator').default,
      require('@babel/plugin-transform-optional-chaining').default,
      require('@babel/plugin-transform-modules-commonjs').default,
      require('@babel/plugin-transform-private-methods').default,
    ];

    const isTs = /\.tsx?$/.test(transformFile);
    const parserPreset = isTs
      ? [require('@babel/preset-typescript').default, { isTSX: true, allExtensions: true }]
      : [require('@babel/preset-flow').default];

    const presets = [parserPreset];
    try {
      presets.push(require('@babel/preset-env').default);
    } catch (e) {}

    require('@babel/register')({
      plugins: defaultPlugins,
      presets: presets,
      only: [transformFile],
      babelrc: false,
    });
  } catch (err) {
    // If babel registration fails, continue and let require fail if syntax error
  }
}

let transformModule;
try {
  const resolvedPath = path.resolve(process.cwd(), transformFile);
  transformModule = require(resolvedPath);
} catch (err) {
  process.stderr.write(`Error loading transform file ${transformFile}: ${err.message}\n`);
  process.exit(1);
}

const transform = typeof transformModule.default === 'function' ? transformModule.default : transformModule;
const parserFromTransform = transformModule.parser;

function trimStackTrace(stack) {
  if (!stack) return '';
  const lines = stack.split('\n');
  return lines.filter(line => !line.includes(__filename) && !line.includes('transform-host.js')).join('\n');
}

function send(msg) {
  process.stdout.write(JSON.stringify(msg) + '\n');
}

async function processFile(file, options) {
  let parser;
  if (parserFromTransform) {
    parser = typeof parserFromTransform === 'string' ? getParser(parserFromTransform) : parserFromTransform;
  } else if (options.parser) {
    parser = getParser(options.parser, options.parserConfig);
  } else {
    parser = getParser();
  }

  const j = core.withParser(parser);

  const stats = (name, quantity) => {
    quantity = typeof quantity !== 'number' ? 1 : quantity;
    send({ action: 'update', name, quantity });
  };
  const empty = () => {};

  const api = {
    j,
    jscodeshift: j,
    stats: options.dry ? stats : empty,
    report: msg => send({ action: 'report', file, msg }),
  };

  try {
    const source = fs.readFileSync(file, 'utf8');
    const out = await transform({ path: file, source }, api, options);

    if (out === undefined || out === null) {
      send({ action: 'status', status: 'skip', file });
    } else if (out === source) {
      send({ action: 'status', status: 'nochange', file });
    } else {
      if (options.print) {
        send({ action: 'print', content: out });
      }
      if (!options.dry) {
        writeFileAtomic.sync(file, out, 'utf8');
      }
      send({ action: 'status', status: 'ok', file });
    }
  } catch (err) {
    const msg = 'Transformation error (' + (err.message || '').replace(/\n/g, ' ') + ')\n' + trimStackTrace(err.stack);
    send({ action: 'status', status: 'error', file, msg });
  }
}

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false,
});

rl.on('line', async line => {
  if (!line.trim()) return;
  try {
    const data = JSON.parse(line);
    if (data.action === 'run') {
      const files = data.files || [];
      const options = data.options || {};
      for (const file of files) {
        await processFile(file, options);
      }
      send({ action: 'free' });
    } else if (data.action === 'finish') {
      process.exit(0);
    }
  } catch (err) {
    process.stderr.write(`Worker parse error: ${err.message}\n`);
  }
});
