#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "action")]
pub enum HostMessage {
    #[serde(rename = "run")]
    Run {
        files: Vec<String>,
        options: serde_json::Value,
    },
    #[serde(rename = "finish")]
    Finish,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "action")]
pub enum WorkerMessage {
    #[serde(rename = "status")]
    Status {
        status: String,
        file: String,
        msg: Option<String>,
    },
    #[serde(rename = "update")]
    Update {
        name: String,
        quantity: i64,
    },
    #[serde(rename = "report")]
    Report {
        file: String,
        msg: String,
    },
    #[serde(rename = "print")]
    Print {
        content: String,
    },
    #[serde(rename = "free")]
    Free,
}
