{"security_risk":"LOW","path":"/workspace/codebase/src/runner.rs","summary":"Create src/runner.rs","command":"create","file_text":"use crate::args::Options;
use crate::colors::*;
use crate::discovery::{get_all_files, parse_extensions};
use crate::ignore::IgnoreEngine;
use crate::worker::{HostMessage, WorkerMessage};
use std::collections::HashMap;
use std::fs::{self, File};
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, Command, Stdio};
use std::sync::mpsc::{self, Receiver, Sender};
use std::thread;
use std::time::Instant;

struct WorkerProcess {
    stdin: ChildStdin,
    child: Child,
}

enum WorkerEvent {
    Msg {
        worker_id: usize,
        message: WorkerMessage,
    },
    Closed {
        worker_id: usize,
    },
}

#[derive(Default)]
struct FileCounters {
    error: usize,
    nochange: usize,
    skip: usize,
    ok: usize,
}

fn resolve_bridge_path() -> PathBuf {
    // Check possible locations for bridge/transform-host.js
    let candidate = Path::new("bridge/transform-host.js");
    if candidate.exists() {
        return candidate.to_path_buf();
    }
    let codebase_candidate = Path::new("codebase/bridge/transform-host.js");
    if codebase_candidate.exists() {
        return codebase_candidate.to_path_buf();
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let p1 = dir.join("bridge/transform-host.js");
            if p1.exists() {
                return p1;
            }
            let p2 = dir.join("../../bridge/transform-host.js");
            if p2.exists() {
                return p2;
            }
        }
    }
    PathBuf::from("/workspace/codebase/bridge/transform-host.js")
}

pub fn run(
    mut options: Options,
    positional_paths: &[String],
) -> Result<i32, Box<dyn std::error::Error>> {
    let start_time = Instant::now();

    // 1. Resolve transform path (local file or URL)
    let mut temp_file_guard: Option<tempfile::NamedTempFile> = None;
    let transform_path: String =
        if options.transform.starts_with("http://") || options.transform.starts_with("https://") {
            let ext = Path::new(&options.transform)
                .extension()
                .and_then(|e| e.to_str())
                .unwrap_or("js");
            let suffix = format!(".{}", ext);
            let mut temp = tempfile::Builder::new().suffix(&suffix).tempfile()?;
            let mut res = ureq::get(&options.transform).call()?;
            let mut body = Vec::new();
            std::io::copy(&mut res.body_mut().as_reader(), &mut body)?;
            temp.write_all(&body)?;
            let path_str = temp.path().to_string_lossy().to_string();
            temp_file_guard = Some(temp);
            path_str
        } else {
            options.transform.clone()
        };

    if !Path::new(&transform_path).exists() {
        eprint!(
            "{} Transform file {} does not exist \n",
            badge_error(),
            options.transform
        );
        return Ok(0);
    }

    // 2. Build ignore engine
    let mut ignore_engine = IgnoreEngine::new();
    if options.gitignore {
        ignore_engine.add_from_file(".gitignore");
    }
    for cfg in &options.ignore_config {
        ignore_engine.add_from_file(cfg);
    }
    ignore_engine.add_patterns(&options.ignore_pattern);

    // 3. Collect files
    let extensions = parse_extensions(&options.extensions);
    let mut paths_to_search = positional_paths.to_vec();

    if options.stdin {
        let mut buffer = String::new();
        let stdin = std::io::stdin();
        let mut handle = stdin.lock();
        handle.read_to_string(&mut buffer)?;
        for line in buffer.split('\n') {
            paths_to_search.push(line.to_string());
        }
    }

    let files = get_all_files(&paths_to_search, &extensions, &mut ignore_engine);

    if files.is_empty() {
        if !options.silent {
            print!("No files selected, nothing to do. \n");
            print!("All done. \n");
            print!(
                "Results: \n{}{}{}{}",
                pc_red("0 errors\n"),
                pc_yellow("0 unmodified\n"),
                pc_yellow("0 skipped\n"),
                pc_green("0 ok\n")
            );
            let elapsed = start_time.elapsed().as_secs_f64();
            print!("Time elapsed: {:.3}seconds \n", elapsed);
        }
        return Ok(0);
    }

    // 4. Calculate processes and chunk sizes
    let num_files = files.len();
    let available_cpus = options.cpus.unwrap_or_else(|| {
        let total = num_cpus::get();
        if total > 1 {
            total - 1
        } else {
            1
        }
    });

    let processes = if options.run_in_band {
        1
    } else {
        std::cmp::min(num_files, available_cpus)
    };

    let chunk_size = if processes > 1 {
        std::cmp::min(
            ((num_files as f64 / processes as f64).ceil() as usize).max(1),
            50,
        )
    } else {
        num_files
    };

    if !options.silent {
        print!("Processing {} files... \n", num_files);
        if !options.run_in_band {
            print!("Spawning {} workers...\n", processes);
        }
        if options.dry {
            print!(
                "{}",
                pc_green("Running in dry mode, no files will be written! \n")
            );
        }
    }

    // Prepare chunks
    let mut chunks: Vec<Vec<String>> = Vec::new();
    let mut file_idx = 0;
    while file_idx < num_files {
        let end = std::cmp::min(file_idx + chunk_size, num_files);
        chunks.push(files[file_idx..end].to_vec());
        file_idx = end;
    }

    // 5. Spawn worker processes
    let bridge_path = resolve_bridge_path();
    let (tx, rx): (Sender<WorkerEvent>, Receiver<WorkerEvent>) = mpsc::channel();
    let mut workers: Vec<WorkerProcess> = Vec::new();

    for worker_id in 0..processes {
        let mut child = Command::new("node")
            .arg(&bridge_path)
            .arg(&transform_path)
            .arg(if options.babel { "babel" } else { "no-babel" })
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;

        let stdin = child.stdin.take().expect("Failed to open child stdin");
        let stdout = child.stdout.take().expect("Failed to open child stdout");

        let tx_clone = tx.clone();
        thread::spawn(move || {
            let reader = BufReader::new(stdout);
            for line_res in reader.lines() {
                if let Ok(line) = line_res {
                    if let Ok(msg) = serde_json::from_str::<WorkerMessage>(&line) {
                        let _ = tx_clone.send(WorkerEvent::Msg {
                            worker_id,
                            message: msg,
                        });
                    }
                }
            }
            let _ = tx_clone.send(WorkerEvent::Closed { worker_id });
        });

        workers.push(WorkerProcess { stdin, child });
    }

    // Build serialized options to send to worker
    let mut options_json = serde_json::json!({
        "dry": options.dry,
        "print": options.print,
        "babel": options.babel,
        "parser": options.parser,
        "parserConfig": options.parser_config,
        "verbose": options.verbose,
        "failOnError": options.fail_on_error,
        "silent": options.silent,
    });
    if let serde_json::Value::Object(ref mut map) = options_json {
        for (k, v) in &options.custom_options {
            map.insert(k.clone(), v.clone());
        }
    }

    // Send initial chunks
    let mut chunk_iter = chunks.into_iter();
    for (worker_id, worker) in workers.iter_mut().enumerate() {
        if let Some(chunk) = chunk_iter.next() {
            if !options.silent && !options.run_in_band {
                print!("Sending {} files to free worker...\n", chunk.len());
            }
            let msg = HostMessage::Run {
                files: chunk,
                options: options_json.clone(),
            };
            let serialized = serde_json::to_string(&msg)?;
            worker.stdin.write_all(serialized.as_bytes())?;
            worker.stdin.write_all(b"\n")?;
            worker.stdin.flush()?;
        }
    }

    // Event loop
    let mut file_counters = FileCounters::default();
    let mut stats: HashMap<String, i64> = HashMap::new();
    let mut active_workers = processes;

    while active_workers > 0 {
        match rx.recv() {
            Ok(WorkerEvent::Msg {
                worker_id,
                message,
            }) => match message {
                WorkerMessage::Status { status, file, msg } => {
                    let full_msg = if let Some(ref m) = msg {
                        format!("{} {}", file, m)
                    } else {
                        file
                    };

                    match status.as_str() {
                        "ok" => {
                            file_counters.ok += 1;
                            if options.verbose >= 2 && !options.silent {
                                println!("{}{}", badge_okk(), full_msg);
                            }
                        }
                        "nochange" => {
                            file_counters.nochange += 1;
                            if options.verbose >= 1 && !options.silent {
                                println!("{}{}", badge_noc(), full_msg);
                            }
                        }
                        "skip" => {
                            file_counters.skip += 1;
                            if options.verbose >= 1 && !options.silent {
                                println!("{}{}", badge_skip(), full_msg);
                            }
                        }
                        "error" => {
                            file_counters.error += 1;
                            if options.verbose >= 0 && !options.silent {
                                println!("{}{}", badge_err(), full_msg);
                            }
                        }
                        _ => {}
                    }
                }
                WorkerMessage::Update { name, quantity } => {
                    *stats.entry(name).or_insert(0) += quantity;
                }
                WorkerMessage::Report { file, msg } => {
                    if !options.silent {
                        println!("{}{} {}", badge_rep(), file, msg);
                    }
                }
                WorkerMessage::Print { content } => {
                    if !options.silent {
                        println!("{}", content);
                    }
                }
                WorkerMessage::Free => {
                    if let Some(chunk) = chunk_iter.next() {
                        if !options.silent && !options.run_in_band {
                            print!("Sending {} files to free worker...\n", chunk.len());
                        }
                        let msg = HostMessage::Run {
                            files: chunk,
                            options: options_json.clone(),
                        };
                        let serialized = serde_json::to_string(&msg)?;
                        let w = &mut workers[worker_id];
                        w.stdin.write_all(serialized.as_bytes())?;
                        w.stdin.write_all(b"\n")?;
                        w.stdin.flush()?;
                    } else {
                        active_workers -= 1;
                        let msg = HostMessage::Finish;
                        let serialized = serde_json::to_string(&msg)?;
                        let w = &mut workers[worker_id];
                        let _ = w.stdin.write_all(serialized.as_bytes());
                        let _ = w.stdin.write_all(b"\n");
                        let _ = w.stdin.flush();
                    }
                }
            },
            Ok(WorkerEvent::Closed { .. }) => {
                // If a worker closed unexpectedly
                active_workers = active_workers.saturating_sub(1);
            }
            Err(_) => break,
        }
    }

    // Wait for worker processes to exit
    for mut worker in workers {
        let _ = worker.child.wait();
    }

    // 6. Summary output
    let elapsed = start_time.elapsed().as_secs_f64();
    if !options.silent {
        print!("All done. \n");
        print!(
            "Results: \n{}{}{}{}",
            pc_red(&format!("{} errors\n", file_counters.error)),
            pc_yellow(&format!("{} unmodified\n", file_counters.nochange)),
            pc_yellow(&format!("{} skipped\n", file_counters.skip)),
            pc_green(&format!("{} ok\n", file_counters.ok))
        );
        if !stats.is_empty() {
            print!("{}", pc_blue("Stats: \n"));
            let mut sorted_keys: Vec<_> = stats.keys().collect();
            sorted_keys.sort();
            for k in sorted_keys {
                println!("{}: {}", k, stats[k]);
            }
        }
        print!("Time elapsed: {:.3}seconds \n", elapsed);
    }

    if options.fail_on_error && file_counters.error > 0 {
        return Ok(1);
    }

    Ok(0)
}
"}

