{"file_text":"use serde_json::Value;

pub fn match_node(haystack: &Value, needle: &Value) -> bool {
    match needle {
        Value::Null => haystack.is_null(),
        Value::Bool(b) => haystack.as_bool() == Some(*b),
        Value::Number(n) => haystack.as_number() == Some(n),
        Value::String(s) => haystack.as_str() == Some(s),
        Value::Array(needle_arr) => {
            if let Value::Array(haystack_arr) = haystack {
                if needle_arr.len() > haystack_arr.len() {
                    return false;
                }
                needle_arr
                    .iter()
                    .zip(haystack_arr.iter())
                    .all(|(n, h)| match_node(h, n))
            } else {
                false
            }
        }
        Value::Object(needle_obj) => {
            if let Value::Object(haystack_obj) = haystack {
                for (key, needle_val) in needle_obj {
                    match haystack_obj.get(key) {
                        Some(haystack_val) => {
                            if !match_node(haystack_val, needle_val) {
                                return false;
                            }
                        }
                        None => return false,
                    }
                }
                true
            } else {
                false
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn test_match_node() {
        let haystack = json!({
            "type": "Identifier",
            "name": "foo",
            "loc": { "start": 0, "end": 3 }
        });

        assert!(match_node(&haystack, &json!({ "type": "Identifier", "name": "foo" })));
        assert!(!match_node(&haystack, &json!({ "type": "Identifier", "name": "bar" })));
    }
}
