{"command":"create","file_text":"use serde_json::Value;

#[derive(Debug, Clone)]
pub struct Collection<T> {
    elements: Vec<T>,
}

impl<T: Clone> Collection<T> {
    pub fn from_nodes(nodes: Vec<T>) -> Self {
        Self { elements: nodes }
    }

    pub fn size(&self) -> usize {
        self.elements.len()
    }

    pub fn length(&self) -> usize {
        self.elements.len()
    }

    pub fn nodes(&self) -> &[T] {
        &self.elements
    }

    pub fn get(&self, index: usize) -> Option<&T> {
        self.elements.get(index)
    }

    pub fn filter<F>(&self, predicate: F) -> Self
    where
        F: Fn(&T) -> bool,
    {
        Self {
            elements: self.elements.iter().filter(|e| predicate(e)).cloned().collect(),
        }
    }

    pub fn for_each<F>(&self, mut f: F)
    where
        F: FnMut(&T),
    {
        for item in &self.elements {
            f(item);
        }
    }

    pub fn some<F>(&self, predicate: F) -> bool
    where
        F: Fn(&T) -> bool,
    {
        self.elements.iter().any(predicate)
    }

    pub fn every<F>(&self, predicate: F) -> bool
    where
        F: Fn(&T) -> bool,
    {
        self.elements.iter().all(predicate)
    }

    pub fn map<U, F>(&self, f: F) -> Vec<U>
    where
        F: Fn(&T) -> U,
    {
        self.elements.iter().map(f).collect()
    }
}

